window.onload=function(){document.querySelectorAll(".cf-field.cf-textarea").forEach((e=>{const n=[...e.classList].filter((e=>e.startsWith("limit-")));if(n.length>0){const t=parseInt(n[0].split("-")[1]);e.querySelector("textarea").addEventListener("input",(function(){this.value.split("\n").length>t&&(this.value=this.value.split("\n").slice(0,t).join("\n"))}))}})),document.querySelectorAll(".carbon-valoracion").forEach((e=>{e.addEventListener("input",(function(){e.value<e.min?e.value=e.min:e.value>e.max&&(e.value=e.max)})),e.addEventListener("keydown",(function(n){"ArrowUp"===n.key&&e.value<e.max?(e.value++,n.preventDefault()):"ArrowDown"===n.key&&e.value>e.min&&(e.value--,n.preventDefault())})),e.addEventListener("blur",(function(){""===e.value&&(e.value=e.min)}))}));const e=document.getElementById("btn-seguridad"),n=document.getElementById("plugins-proceso");e&&n&&e.addEventListener("click",(function(){this.disabled=!0,this.textContent="Instalando...",n.innerHTML="<p>Procesando solicitud. No cambies de página, espera hasta que termine.</p>",fetch(ajaxData.ajax_url,{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body:new URLSearchParams({action:"instalar_plugins_seguridad",nonce:ajaxData.nonce})}).then((e=>e.text())).then((e=>{const t=e.indexOf('{"success"'),a=e.lastIndexOf("}");if(-1!==t&&-1!==a){const r=e.substring(t,a+1),o=JSON.parse(r);o.success?(console.log(o.data.message),n.innerHTML="<p>Plugins instalados correctamente. Dirigete hacia los plugins para activarlos</p>"):(console.error(o.data.message||"Error desconocido."),n.textContent=`Error: ${o.data.message||"Error desconocido."}`)}else console.error("No se encontró un JSON válido en la respuesta."),n.innerHTML="<p>Error en la respuesta del servidor.</p>"})).catch((e=>{console.error("Error en la petición:",e),n.innerHTML="<p>Error al procesar la solicitud.</p>"}))}))};